createAIProvider(sdk) <p>Creates an <code>AIContext</code> from explicit AI SDK function references. No dynamic imports.</p> <pre><code>import { createAIProvider } from '@flowforgejs/engine';
import { generateText, streamText, generateObject, embed } from 'ai';

const ai = createAIProvider({ generateText, streamText, generateObject, embed });

const engine = new Engine({ ai });
</code></pre>

AISDKFunctions Interface <pre><code>interface AISDKFunctions {
  generateText: (params: AIRequestParams) =&gt; Promise&lt;AITextResponse&gt;;
  streamText: (params: AIRequestParams) =&gt; Promise&lt;AIStreamResponse&gt;;
  generateObject: (params: AIObjectParams) =&gt; Promise&lt;AIObjectResponse&gt;;
  embed: (params: AIEmbedParams) =&gt; Promise&lt;AIEmbedResponse&gt;;
}
</code></pre>

register(provider: ModelProvider): void <p>Register a model provider.</p> <pre><code>interface ModelProvider {
  name: string; // e.g. "openai", "anthropic"
  models: string[]; // Known model IDs
  createModel(modelId: string): unknown; // Factory function
}
</code></pre> <pre><code>import { openai } from '@ai-sdk/openai';

registry.register({
  name: 'openai',
  models: ['gpt-4o', 'gpt-4o-mini', 'gpt-3.5-turbo'],
  createModel: (id) =&gt; openai(id),
});
</code></pre>

resolve(modelString: string): <p>Resolve a <code>"provider/model"</code> string to a provider and model object.</p> <pre><code>const { provider, model } = registry.resolve('openai/gpt-4o');
// provider.name === 'openai'
// model is the result of openai('gpt-4o')
</code></pre> <p>Throws if the provider is not registered or the string format is invalid.</p>

withRetry(fn, config, ctx) <p>Execute a function with retry logic.</p> <pre><code>import { withRetry } from '@flowforgejs/engine';

const result = await withRetry(
  (attempt) =&gt; fetchData(attempt),
  {
    maxAttempts: 3,
    backoff: 'exponential',
    delayMs: 1000,
    maxDelayMs: 10_000,
  },
  {
    nodeId: 'my-node',
    signal: abortController.signal,
    onRetry: (attempt, error, delayMs) =&gt; {
      console.log(`Retry ${attempt}, waiting ${delayMs}ms: ${error.message}`);
    },
  },
);
</code></pre>
